{"path":"tools/LetUsCook.AutoWrongCensus/AutoWrongCensusCli.cs","content":"using System;
using System.IO;
using System.Threading.Tasks;

using LetUsCook.AutoWrongCensus.HostedServices;

using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

namespace LetUsCook.AutoWrongCensus;

/// <summary>
/// The console entry point: builds the same host graph <c>Program.cs</> uses and returns the
/// hosted service's exit code. Tests call this directly with their own writers, so the golden
/// test exercises the real entry path, not a copy of it.
/// </summary>
public static class AutoWrongCensusCli
{
	/// <summary>
	/// Runs the CLI for <paramref name="args"/>.
	/// </summary>
	/// <param name="args">The command line arguments.</param>
	/// <param name="output">
	/// The writer for the machine-readable TSV output. <see langword="null"/> (the default) uses
	/// <see cref="Console.Out"/>.
	/// </param>
	/// <param name="error">
	/// The writer for the human summary and error lines. <see langword="null"/> (the default) uses
	/// <see cref="Console.Error"/>.
	/// </param>
	/// <returns>The exit code: 0 on success, 1 on a missing file, a refused set, or a bad argument.</returns>
	public static async Task<int> RunAsync(string[] args, TextWriter? output = null, TextWriter? error = null)
	{
		if (Array.Exists(args, a => a.Equals("--help", StringComparison.OrdinalIgnoreCase) || a.Equals("-h", StringComparison.OrdinalIgnoreCase)))
		{
			Options.AutoWrongCensusUsage.Print();
			return 0;
		}

		var builder = AutoWrongCensusHostBuilderFactory.Create(args, output, error);
		var host = builder.Build();

		// Resolve BEFORE RunAsync(): RunAsync disposes the provider on shutdown.
		var hostedService = host.Services.GetRequiredService<AutoWrongCensusHostedService>();
		await host.RunAsync().ConfigureAwait(false);
		return hostedService.ExitCode;
	}
}
