/// <summary>Usage text for the auto-wrong census CLI.</summary>
public static class AutoWrongCensusUsage
{
	/// <summary>Prints the usage to stdout.</summary>
	public static void Print()
	{
		System.Console.WriteLine(
			"LetUsCook.AutoWrongCensus — F-428 P12.13: classify every auto-wrong debug/batch trace line.\n" +
			"\n" +
			"Usage:\n" +
			"  LetUsCook.AutoWrongCensus census <trace.jsonl>\n" +
			"      Classifies every line with auto=true and correct=false. The TSV goes to stdout;\n" +
			"      the relation x site summary goes to stderr. Exits 1 on a missing trace or a\n" +
			"      record whose set is neither 'debug' nor 'batch' (D-029).\n" +
			"\n" +
			"  LetUsCook.AutoWrongCensus pairs <census.tsv> <trace.jsonl>\n" +
			"      For each census row with blocker=window and route compound/other, emits the\n" +
			"      parsedName head and the key head-phrase words (the P12.18 input list).\n");
	}
}
