{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// F-428 P12.13: classifies one auto-wrong trace line on two axes — <em>relation</em> (accepted row
/// vs labelled key row) and <em>site</em> (the decision path that let it through).
/// <para>
/// Every food-side computation calls the production helpers (D-014: a copy is what let the trainer
/// diverge from serving): <see cref="FdcNormalizer.NormalizeToTokens"/>,
/// <see cref="FdcMatcher.ExtractCandidateState"/>, <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>,
/// <see cref="FdcDescriptionParser.Parse"/>, <see cref="IngredientLineResolver.SingularizeToken"/> and
/// <see cref="IngredientLineResolver.ShouldReuse"/>. The state mask is the production composition
/// (FdcMatcher's own <c>ExtractCandidateState | ExtractCandidateSatisfiers</c> pair, FdcMatcher.cs:1155).
/// </para>
/// <para>
/// Relation ladder (first match wins, brief §4): <c>no-label</c>, <c>pack-unit-state</c>,
/// <c>compound-head-lost</c>, <c>state-mismatch</c>, <c>row-choice-tier</c>,
/// <c>same-head-other-qualifier</c>, <c>sibling-food</c>, <c>other</c>. The key head phrase is the
/// leading run of the key's normalised tokens up to the first token the production lexicon
/// (<see cref="FdcLexicon.ModifierWords"/>) or the production state functions report as state-carrying
/// — so "Bread, crumbs, dry, grated, plain" reads as head phrase "bread crumbs" while
/// "Nuts, almonds, blanched" reads as "nut almond".
/// </para>
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>A line with no labelled row.</summary>
	public const string RelationNoLabel = "no-label";

	/// <summary>A can/jar unit in the raw text; the key is canned and the accepted row is not.</summary>
	public const string RelationPackUnitState = "pack-unit-state";

	/// <summary>The key head phrase is two or more words and the parsed name kept only its first word.</summary>
	public const string RelationCompoundHeadLost = "compound-head-lost";

	/// <summary>Same head; the production state masks differ.</summary>
	public const string RelationStateMismatch = "state-mismatch";

	/// <summary>Same head and state; the dataset tier differs.</summary>
	public const string RelationRowChoiceTier = "row-choice-tier";

	/// <summary>Same head, state and tier; only the remaining qualifiers differ.</summary>
	public const string RelationSameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>The heads disagree: a different food.</summary>
	public const string RelationSiblingFood = "sibling-food";

	/// <summary>Nothing above held, or a field the ladder needs is missing from the trace.</summary>
	public const string RelationOther = "other";

	/// <summary>Site: the line reused an existing row (path ranker, reused).</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the exact/special-case override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker accepted without reuse.</summary>
	public const string SiteRanker = "ranker";

	/// <summary>TSV column order (brief §4).</summary>
	public static readonly IReadOnlyList<string> TsvColumns =
	[
		"holdoutId", "lineIndex", "set", "relation", "site", "overrideKey",
		"acceptedTier", "keyTier", "acceptedState", "keyState",
		"parsedName", "keyHead", "acceptedDesc", "keyDesc", "rawText",
	];

	/// <summary>TSV column order for the <c>pairs</c> subcommand.</summary>
	public static readonly IReadOnlyList<string> PairsColumns = ["holdoutId", "lineIndex", "parsedNameHead", "keyHead", "rawText"];

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	/// <summary>Single-slot token list so the per-token state check never allocates (see <see cref="IsStateCarryingToken"/>).</summary>
	private readonly List<string> _singleToken = [];

	private static readonly string[] EmptyTokens = [];

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>Creates a classifier over the production lexicon.</summary>
	/// <param name="normalizer">The production normalizer.</param>
	/// <param name="overrideKeys">The production <c>exact-overrides.json</c> key set.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	/// <summary>
	/// Classifies one auto-wrong line. <see cref="ClassificationResult.Site"/> is <see langword="null"/>
	/// when the trace carries a decision path this instrument does not know; the runner fails the run.
	/// </summary>
	/// <param name="line">A trace line with <c>auto == true && correct == false</c>.</param>
	/// <returns>The relation and site plus every field the TSV and summary need.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var keyDesc = First(line.ExpectedDescriptions);
		var acceptedDesc = First(line.ActualDescriptions);
		var keyTier = First(line.ExpectedDataTypes);
		var acceptedTier = First(line.ActualDataTypes);

		var atom = line.Atoms.FirstOrDefault(a => a.Outcome == "accepted") ?? line.Atoms.FirstOrDefault();
		var parsedName = atom?.ParsedName ?? string.Empty;
		var parsedTokens = SingularPhrase(parsedName);

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);

		var keyHeadParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier));
		var acceptedHeadParsed = string.IsNullOrWhiteSpace(acceptedDesc)
			? null
			: FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier));

		var keyHead = SingularPhrase(keyHeadParsed.HeadTerm);
		var acceptedHead = acceptedHeadParsed is null ? EmptyTokens : SingularPhrase(acceptedHeadParsed.HeadTerm);
		var keyPhrase = KeyHeadPhrase(keyTokens);

		var relation = ClassifyRelation(line, keyDesc, acceptedDesc, parsedTokens, keyPhrase, keyHead, acceptedHead, keyState, acceptedState, keyTier, acceptedTier);

		var (site, overrideKey) = ClassifySite(line, atom);

		return new ClassificationResult(
			HoldoutId: line.HoldoutId,
			LineIndex: line.LineIndex,
			Set: line.Set,
			Relation: relation,
			Site: site,
			OverrideKey: overrideKey,
			AcceptedTier: acceptedTier,
			KeyTier: keyTier,
			AcceptedState: FormatState(acceptedState),
			KeyState: FormatState(keyState),
			ParsedName: parsedName,
			KeyHead: string.Join(' ', keyPhrase),
			AcceptedDesc: acceptedDesc,
			KeyDesc: keyDesc,
			RawText: line.RawText,
			AcceptedQualifiers: acceptedHeadParsed is null ? [] : SingularPhraseList(acceptedHeadParsed.Qualifiers),
			KeyQualifiers: SingularPhraseList(keyHeadParsed.Qualifiers),
			ShouldReuseLinkedMaster: ShouldReuseLinkedMaster(parsedName, atom?.LinkedIngredientId));
	}

	/// <summary>
	/// The key head phrase: the leading run of the key's normalised tokens up to the first token the
	/// production lexicon or state functions report as state-carrying.
	/// </summary>
	/// <param name="keyTokens">Normalised tokens of the key description.</param>
	/// <returns>The head-phrase tokens, in order.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		ArgumentNullException.ThrowIfNull(keyTokens);
		var phrase = new List<string>(keyTokens.Count);
		foreach (var token in keyTokens)
		{
			if (IsStateCarryingToken(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>
	/// The production state mask for a token list: <see cref="FdcMatcher.ExtractCandidateState"/>
	/// ORed with <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>, the same composition the matcher
	/// feeds its <c>StateAgrees</c> checks (FdcMatcher.cs:1155).
	/// </summary>
	/// <param name="tokens">A normalised token list.</param>
	/// <returns>The combined state mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// The production reuse rule (F-428 P6.6 exact-phrase equality) applied to the line's own parsed
	/// name against the master it linked: <see langword="true"/> when the resolver's
	/// <see cref="IngredientLineResolver.ShouldReuse"/> says the phrase is the master's,
	/// <see langword="false"/> when it would not have matched by name (the link came via fdcId),
	/// <see langword="null"/> when the trace carries no linked master.
	/// </summary>
	/// <param name="parsedName">The atom's parsed name.</param>
	/// <param name="linkedIngredientId">The linked master slug, or null.</param>
	/// <returns>The production rule's verdict, or null when not applicable.</returns>
	public static bool? ShouldReuseLinkedMaster(string parsedName, string? linkedIngredientId)
	{
		if (string.IsNullOrWhiteSpace(parsedName) || string.IsNullOrWhiteSpace(linkedIngredientId))
		{
			return null;
		}

		return IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(parsedName), linkedIngredientId);
	}

	private string ClassifyRelation(
		TraceLine line,
		string keyDesc,
		string acceptedDesc,
		IReadOnlyList<string> parsedTokens,
		IReadOnlyList<string> keyPhrase,
		IReadOnlyList<string> keyHead,
		IReadOnlyList<string> acceptedHead,
		FoodState keyState,
		FoodState acceptedState,
		string keyTier,
		string acceptedTier)
	{
		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			return RelationNoLabel;
		}

		if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != 0
			&& (acceptedState & FoodState.Canned) == 0)
		{
			return RelationPackUnitState;
		}

		if (keyPhrase.Count >= 2
			&& parsedTokens.Count == 1
			&& string.Equals(parsedTokens[0], IngredientLineResolver.SingularizeToken(keyPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			return RelationCompoundHeadLost;
		}

		if (string.IsNullOrWhiteSpace(acceptedDesc))
		{
			return RelationOther;
		}

		var headsAgree = keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase);
		if (!headsAgree)
		{
			return RelationSiblingFood;
		}

		if (keyState != acceptedState)
		{
			return RelationStateMismatch;
		}

		if (string.IsNullOrWhiteSpace(keyTier) || string.IsNullOrWhiteSpace(acceptedTier))
		{
			return RelationOther;
		}

		if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
		{
			return RelationRowChoiceTier;
		}

		return RelationSameHeadOtherQualifier;
	}

	private (string? Site, string? OverrideKey) ClassifySite(TraceLine line, TraceAtom? atom)
	{
		if (atom is null)
		{
			return (null, null);
		}

		switch (atom.Path)
		{
			case "override":
				return (SiteOverride, _overrideKeys.ContainsRaw(line.RawText) ? "yes" : "no");

			case "curated":
				return (SiteCurated, null);

			case "ranker":
				return (atom.Reused ? SiteReuse : SiteRanker, null);

			default:
				return (null, null);
		}
	}

	private static bool IsStateCarryingToken(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		// The production per-token state/satisfier verdict. The matcher's own functions take a token
		// list; a single-slot list keeps this allocation-free.
		_singleToken[0] = token;
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	private static string First(IReadOnlyList<string> values)
	{
		var first = values.FirstOrDefault();
		return string.IsNullOrWhiteSpace(first) ? string.Empty : first!;
	}

	private IReadOnlyList<string> SingularPhrase(string text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private static IReadOnlyList<string> SingularPhraseList(IReadOnlyList<string> tokens) =>
		tokens.Select(IngredientLineResolver.SingularizeToken).ToArray();

	private static string FormatState(FoodState state) => state == FoodState.None ? "None" : state.ToString();
}
