{"content":"using System.Collections.Frozen;
using System.Text.Json;

using LetUsCook.Fdc.Lexicon;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The key set of <c>src/LetUsCook.Fdc/Lexicon/Resources/exact-overrides.json</c>, read from the
/// production assembly's embedded copy (the same file the shipped lexicon is built from). This is a
/// data read, not matcher logic — D-014 forbids copies of the matching rules, not of the table's keys.
/// </summary>
public sealed class ExactOverrideKeyIndex
{
	private readonly FrozenSet<string> _keys;

	private ExactOverrideKeyIndex(FrozenSet<string> keys)
	{
		_keys = keys;
	}

	/// <summary>Loads the index from the <c>LetUsCook.Fdc</c> assembly.</summary>
	/// <returns>A ready-to-query index.</returns>
	public static ExactOverrideKeyIndex Load()
	{
		var assembly = typeof(FdcNormalizer).Assembly;
		var name = assembly.GetManifestResourceNames().Single(n => n.EndsWith("exact-overrides.json", StringComparison.Ordinal));
		using var stream = assembly.GetManifestResourceStream(name)
			?? throw new InvalidOperationException($"Embedded resource '{name}' not found.");
		using var reader = new StreamReader(stream);
		var entries = JsonSerializer.Deserialize<Dictionary<string, JsonElement>>(reader.ReadToEnd())
			?? throw new InvalidOperationException("exact-overrides.json was empty.");

		return new ExactOverrideKeyIndex(entries.Keys.ToFrozenSet(StringComparer.OrdinalIgnoreCase));
	}

	/// <summary>Whether <paramref name="key"/> is an exact-override key (case-insensitive).</summary>
	/// <param name="key">A cleaned ingredient name.</param>
	public bool Contains(string key) => _keys.Contains(key);
}
