{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes — the accepted row vs the key row
/// <see cref="ClassificationResult.Relation"/>, and the decision <see cref="ClassificationResult.Site"/>.
/// <para>
/// Every food-side computation calls the production helpers (D-014): <see cref="FdcNormalizer.NormalizeToTokens"/>,
/// <see cref="FdcMatcher.ExtractCandidateState"/>, <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>,
/// <see cref="FdcDescriptionParser.Parse"/>, <see cref="IngredientLineResolver.SingularizeToken"/> and
/// <see cref="IngredientLineResolver.ShouldReuse"/>. Nothing here re-implements matcher logic.
/// </para>
/// <para>
/// The <c>compound-head-lost</c> rule needs a head phrase, not the parser's single-token
/// <see cref="ParsedFdcDescription.HeadTerm"/>: the key description's tokens up to the first word the
/// production state/modifier vocabulary flags (F-428 P12.13 — the brief's bread-crumbs example has a
/// one-token parser head, so the phrase is derived from the same production word lists the matcher uses).
/// </para>
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the labelled row is missing.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: a can/jar unit line accepted on a row without the key's Canned state.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase is compound and the parsed name kept only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: the same head, different state masks.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: the same head and state on a different dataset tier.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: the same head, state and tier, different qualifiers.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: no rule matched, or a check needed a field the trace does not carry.</summary>
	public const string Other = "other";

	/// <summary>Site: fdcId→master reuse on the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the shortcut override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue path.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker without reuse.</summary>
	public const string SiteRanker = "ranker";

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	/// <summary>Reused single-token list for the per-token state checks (single-threaded runner).</summary>
	private readonly List<string> _singleToken = [];

	/// <summary>Creates a classifier over the production normalizer and the exact-override key set.</summary>
	/// <param name="normalizer">The production FDC normalizer.</param>
	/// <param name="overrideKeys">The exact-override raw-key index.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	/// <summary>
	/// Classifies one auto-wrong line. The first relation rule that holds wins, in the brief's order:
	/// no-label → pack-unit-state → compound-head-lost → state-mismatch → row-choice-tier →
	/// same-head-other-qualifier → sibling-food → other.
	/// </summary>
	/// <param name="line">The trace line (<c>auto == true && correct == false</c>).</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var keyDesc = First(line.ExpectedDescriptions);
		var acceptedDesc = First(line.ActualDescriptions);
		var keyTier = First(line.ExpectedDataTypes);
		var acceptedTier = First(line.ActualDataTypes);
		var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase))
			?? line.Atoms.FirstOrDefault();

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);

		var keyHeadParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier));
		var acceptedHeadParsed = string.IsNullOrWhiteSpace(acceptedDesc)
			? new ParsedFdcDescription(string.Empty, [], null)
			: FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier));

		var keyHead = SingularPhrase(keyHeadParsed.HeadTerm);
		var acceptedHead = SingularPhrase(acceptedHeadParsed.HeadTerm);
		var parsedNameTokens = SingularPhrase(atom?.ParsedName ?? string.Empty);
		var keyPhrase = KeyHeadPhrase(keyTokens);

		var result = new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = atom?.ParsedName ?? string.Empty,
			KeyHead = string.Join(' ', keyPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
		};

		result.Site = SiteOf(atom, line.RawText);

		result.Relation = string.IsNullOrWhiteSpace(keyDesc)
			? NoLabel
			: ClassifyRelation(keyDesc, acceptedDesc, keyTier, acceptedTier, keyTokens, keyState, acceptedState, keyHeadParsed, acceptedHeadParsed, keyHead, acceptedHead, keyPhrase, parsedNameTokens, line.RawText, result);

		return result;
	}

	/// <summary>The key description's head phrase: tokens up to the first production state/modifier word.</summary>
	/// <param name="keyTokens">The production-normalized key description tokens.</param>
	/// <returns>The head phrase tokens (possibly one or zero words).</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		ArgumentNullException.ThrowIfNull(keyTokens);
		var phrase = new List<string>(keyTokens.Count);
		foreach (var token in keyTokens)
		{
			if (IsStateOrModifierWord(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>Whether the production state/modifier vocabulary flags <paramref name="token"/> as a state word.</summary>
	/// <param name="token">A normalized token.</param>
	/// <returns>Whether the word carries state for the matcher.</returns>
	public bool IsStateOrModifierWord(string token)
	{
		ArgumentNullException.ThrowIfNull(token);

		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleToken.Clear();
		_singleToken.Add(token);
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}

	/// <summary>The combined production state mask for a token list: <c>ExtractCandidateState | ExtractCandidateSatisfiers</c>.</summary>
	/// <param name="tokens">The production-normalized tokens.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// Whether the resolver's own exact-phrase reuse rule accepts the parsed name for the linked master.
	/// Census statistic for <c>reuse</c>-site lines (D-014: the production rule, not a copy).
	/// </summary>
	/// <param name="parsedName">The parser name.</param>
	/// <param name="linkedIngredientId">The linked master slug.</param>
	/// <returns>Whether <see cref="IngredientLineResolver.ShouldReuse"/> holds; <see langword="false"/> when either side is empty.</returns>
	public bool ShouldReuseParsedNameForLinkedMaster(string parsedName, string? linkedIngredientId)
	{
		if (string.IsNullOrWhiteSpace(parsedName) || string.IsNullOrWhiteSpace(linkedIngredientId))
		{
			return false;
		}

		return IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(parsedName), linkedIngredientId);
	}

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	private static string First(IReadOnlyList<string> values)
	{
		for (var i = 0; i < values.Count; i++)
		{
			if (!string.IsNullOrWhiteSpace(values[i]))
			{
				return values[i];
			}
		}

		return string.Empty;
	}

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, out var dataset) ? dataset : FdcDataset.None;

	private static string SiteOf(TraceAtom? atom, string rawText)
	{
		if (atom is null)
		{
			return string.Empty;
		}

		return atom.Path.ToLowerInvariant() switch
		{
			"override" => SiteOverride,
			"curated" => SiteCurated,
			"ranker" => atom.Reused ? SiteReuse : SiteRanker,
			_ => string.Empty,
		};
	}

	private string ClassifyRelation(
		string keyDesc,
		string acceptedDesc,
		string keyTier,
		string acceptedTier,
		IReadOnlyList<string> keyTokens,
		FoodState keyState,
		FoodState acceptedState,
		ParsedFdcDescription keyHeadParsed,
		ParsedFdcDescription acceptedHeadParsed,
		IReadOnlyList<string> keyHead,
		IReadOnlyList<string> acceptedHead,
		IReadOnlyList<string> keyPhrase,
		IReadOnlyList<string> parsedNameTokens,
		string rawText,
		ClassificationResult result)
	{
		// 1. no-label is handled by the caller.
		if (PackUnitRegex().IsMatch(rawText)
			&& (keyState & FoodState.Canned) != FoodState.None
			&& (acceptedState & FoodState.Canned) == FoodState.None)
		{
			return PackUnitState;
		}

		if (keyPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			return CompoundHeadLost;
		}

		var headsAgree = keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase);

		if (headsAgree)
		{
			if (keyState != acceptedState)
			{
				return StateMismatch;
			}

			if (string.IsNullOrWhiteSpace(keyTier) || string.IsNullOrWhiteSpace(acceptedTier))
			{
				result.MissingField = string.IsNullOrWhiteSpace(keyTier) ? "expectedDataTypes" : "actualDataTypes";
				return Other;
			}

			if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
			{
				return RowChoiceTier;
			}

			result.KeyOnlyQualifiers = QualifierDiff(keyHeadParsed, acceptedHeadParsed, keyOnly: true);
			result.AcceptedOnlyQualifiers = QualifierDiff(keyHeadParsed, acceptedHeadParsed, keyOnly: false);
			return SameHeadOtherQualifier;
		}

		return SiblingFood;
	}

	private static IReadOnlyList<string> QualifierDiff(ParsedFdcDescription key, ParsedFdcDescription accepted, bool keyOnly)
	{
		var keySet = new HashSet<string>(key.Qualifiers.Select(IngredientLineResolver.SingularizeToken), StringComparer.OrdinalIgnoreCase);
		var acceptedSet = new HashSet<string>(accepted.Qualifiers.Select(IngredientLineResolver.SingularizeToken), StringComparer.OrdinalIgnoreCase);

		var diff = key.Qualifiers.Select(IngredientLineResolver.SingularizeToken)
			.Where(t => keyOnly ? !acceptedSet.Contains(t) : keySet.Contains(t))
			.Distinct(StringComparer.OrdinalIgnoreCase)
			.OrderBy(t => t, StringComparer.OrdinalIgnoreCase)
			.ToList();

		return keyOnly
			? diff
			: accepted.Qualifiers.Select(IngredientLineResolver.SingularizeToken)
				.Where(t => !keySet.Contains(t))
				.Distinct(StringComparer.OrdinalIgnoreCase)
				.OrderBy(t => t, StringComparer.OrdinalIgnoreCase)
				.ToList();
	}

	private IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text)
			.Select(IngredientLineResolver.SingularizeToken)
			.ToList();
}
