{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes — the accepted row vs the key row <b>relation</b>
/// and the decision <b>site</b> — using the production helpers (F-428 P12.13, D-014):
/// <see cref="FdcNormalizer.NormalizeToTokens(string)"/> for token folding,
/// <see cref="FdcMatcher.ExtractCandidateState(IReadOnlyList{string})"/>/
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers(IReadOnlyList{string})"/> for the state masks,
/// <see cref="FdcDescriptionParser.Parse(string, FdcDataset, string?)"/> for head terms, and
/// <see cref="IngredientLineResolver.SingularizeToken(string)"/> for singularisation.
/// <para>
/// Relation order (first that holds wins): <c>no-label</c>, <c>pack-unit-state</c>,
/// <c>compound-head-lost</c>, <c>state-mismatch</c>, <c>row-choice-tier</c>,
/// <c>same-head-other-qualifier</c>, <c>sibling-food</c>, <c>other</c>.
/// The key head phrase is the key description's normalized tokens up to the first token the
/// production state/modifier vocabulary flags, so "Bread, crumbs, dry, grated, plain" reads as the
/// two-word head "bread crumbs" while "Nuts, almonds, blanched" reads as "nut almond".
/// </para>
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary><c>no-label</c>: the line carries no labelled row.</summary>
	public const string NoLabel = "no-label";

	/// <summary><c>pack-unit-state</c>: a can/jar unit in the raw text, the key row canned, the accepted row not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary><c>compound-head-lost</c>: the key head phrase is multi-word and the parsed name is only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary><c>state-mismatch</c>: the head terms agree but the state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary><c>row-choice-tier</c>: head and state agree but the dataset tiers differ.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary><c>same-head-other-qualifier</c>: head, state and tier agree; only qualifiers differ.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary><c>sibling-food</c>: the head terms differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary><c>other</c>: nothing above held, or a relation check lacked a trace field.</summary>
	public const string Other = "other";

	/// <summary><c>reuse</c>: ranker path, an existing master row was reused.</summary>
	public const string SiteReuse = "reuse";

	/// <summary><c>ranker</c>: ranker path, no reuse.</summary>
	public const string SiteRanker = "ranker";

	/// <summary><c>override</c>: the exact-override path.</summary>
	public const string SiteOverride = "override";

	/// <summary><c>curated</c>: the curated-catalogue path.</summary>
	public const string SiteCurated = "curated";

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Single-element scratch for the per-token state checks: the classifier is consumed by one runner
	// thread at a time, and the production helpers take an IReadOnlyList, so no per-token allocation.
	private readonly string?[] _singleTokenScratch = new string[1];

	/// <summary>Creates a classifier over the production normalizer and the exact-override key set.</summary>
	/// <param name="normalizer">The production <see cref="FdcNormalizer"/>.</param>
	/// <param name="overrideKeys">The <c>exact-overrides.json</c> key set.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>
	/// Classifies one auto-wrong line. The caller must have filtered to <c>auto == true &amp;&amp; correct == false</c>.
	/// </summary>
	/// <param name="line">The trace line.</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var keyDesc = First(line.ExpectedDescriptions);
		var acceptedDesc = First(line.ActualDescriptions);
		var keyTier = First(line.ExpectedDataTypes);
		var acceptedTier = First(line.ActualDataTypes);

		var atom = line.Atoms.FirstOrDefault(a => a.Outcome == "accepted") ?? line.Atoms.FirstOrDefault();
		var parsedName = atom?.ParsedName ?? string.Empty;

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);

		var keyHead = SingularPhrase(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).HeadTerm);
		var acceptedHead = string.IsNullOrWhiteSpace(acceptedDesc)
			? []
			: SingularPhrase(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).HeadTerm);
		var parsedNameTokens = SingularPhrase(parsedName);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);

		var result = new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = FormatMask(acceptedState),
			KeyState = FormatMask(keyState),
			ParsedName = parsedName,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
		};

		result.Site = ClassifySite(atom, line.RawText, out var overrideKey);
		result.OverrideKey = overrideKey;
		if (result.Site.Length == 0)
		{
			return result;
		}

		result.Relation = ClassifyRelation(line, keyDesc, acceptedDesc, keyTier, acceptedTier, keyState, acceptedState, keyHead, acceptedHead, parsedNameTokens, keyHeadPhrase);
		return result;
	}

	/// <summary>
	/// The key description's head phrase: normalized tokens up to (excluding) the first token the
	/// production state/modifier vocabulary flags. "Bread, crumbs, dry, grated, plain" → "bread crumbs".
	/// </summary>
	/// <param name="keyTokens">Normalized key description tokens.</param>
	/// <returns>The head phrase tokens (possibly empty).</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		var phrase = new List<string>(keyTokens.Count);
		foreach (var token in keyTokens)
		{
			if (CarriesStateOrModifier(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>
	/// The production state mask for a token list: <see cref="FdcMatcher.ExtractCandidateState(IReadOnlyList{string})"/>
	/// unioned with <see cref="FdcMatcher.ExtractCandidateSatisfiers(IReadOnlyList{string})"/>, the same
	/// composition <c>FdcMatcher</c> feeds to its <c>StateAgrees</c> checks.
	/// </summary>
	/// <param name="tokens">Normalized description tokens.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	private string ClassifySite(TraceAtom? atom, string rawText, out string overrideKey)
	{
		overrideKey = string.Empty;
		if (atom is null)
		{
			return string.Empty;
		}

		return atom.Path switch
		{
			"override" => SiteOverride,
			"curated" => SiteCurated,
			"ranker" => atom.Reused ? SiteReuse : SiteRanker,
			_ => string.Empty,
		};
	}

	private string ClassifyRelation(
		TraceLine line,
		string keyDesc,
		string acceptedDesc,
		string keyTier,
		string acceptedTier,
		FoodState keyState,
		FoodState acceptedState,
		IReadOnlyList<string> keyHead,
		IReadOnlyList<string> acceptedHead,
		IReadOnlyList<string> parsedNameTokens,
		IReadOnlyList<string> keyHeadPhrase)
	{
		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			return NoLabel;
		}

		if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != FoodState.None
			&& (acceptedState & FoodState.Canned) == FoodState.None)
		{
			return PackUnitState;
		}

		if (keyHeadPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			return CompoundHeadLost;
		}

		var headsAgree = keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase);
		if (!headsAgree)
		{
			return SiblingFood;
		}

		if (keyState != acceptedState)
		{
			return StateMismatch;
		}

		if (string.IsNullOrEmpty(keyTier) || string.IsNullOrEmpty(acceptedTier))
		{
			line.MissingField = "dataTypes";
			return Other;
		}

		if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
		{
			return RowChoiceTier;
		}

		RecordQualifierDiff(line, keyDesc, acceptedDesc, keyTier, acceptedTier);
		return SameHeadOtherQualifier;
	}

	private void RecordQualifierDiff(TraceLine line, string keyDesc, string acceptedDesc, string keyTier, string acceptedTier)
	{
		var keyQualifiers = SingularPhrase(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).HeadTerm) is var head && head.Count > 0
			? []
			: [];
		// The parser's Qualifiers are the description tokens minus the head; singularise both sides and diff.
		var keySet = ToQualifierSet(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).Qualifiers);
		var acceptedSet = ToQualifierSet(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).Qualifiers);

		line.KeyOnlyQualifiers = keySet.Except(acceptedSet).OrderBy(t => t, StringComparer.OrdinalIgnoreCase).ToArray();
		line.AcceptedOnlyQualifiers = acceptedSet.Except(keySet).OrderBy(t => t, StringComparer.OrdinalIgnoreCase).ToArray();
	}

	private static HashSet<string> ToQualifierSet(IReadOnlyList<string> qualifiers) =>
		qualifiers
			.Select(IngredientLineResolver.SingularizeToken)
			.ToHashSet(StringComparer.OrdinalIgnoreCase);

	private bool CarriesStateOrModifier(string token)
	{
		_singleTokenScratch[0] = token;
		return FdcLexicon.Default.ModifierWords.Contains(token)
			|| FdcMatcher.ExtractCandidateState(_singleTokenScratch) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleTokenScratch) != FoodState.None;
	}

	private IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private static string First(IReadOnlyList<string> values)
	{
		for (var i = 0; i < values.Count; i++)
		{
			if (!string.IsNullOrWhiteSpace(values[i]))
			{
				return values[i];
			}
		}

		return string.Empty;
	}

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	private static string FormatMask(FoodState mask) => mask == FoodState.None ? "None" : mask.ToString();
}
