using Shouldly;

using Xunit;

namespace LetUsCook.AutoWrongCensus.Tests.Options;

public sealed class CommandLineArgumentParserTests
{
	[Fact]
	public void ParseMapsCensusWithTracePath()
	{
		var result = CommandLineArgumentParser.Parse(["census", "/tmp/trace.jsonl"]);

		result["AutoWrongCensus:Command"].ShouldBe("census");
		result["AutoWrongCensus:TracePath"].ShouldBe("/tmp/trace.jsonl");
	}

	[Fact]
	public void ParseMapsPairsWithCensusTsvAndTracePath()
	{
		var result = CommandLineArgumentParser.Parse(["pairs", "/tmp/census.tsv", "/tmp/trace.jsonl"]);

		result["AutoWrongCensus:Command"].ShouldBe("pairs");
		result["AutoWrongCensus:CensusTsvPath"].ShouldBe("/tmp/census.tsv");
		result["AutoWrongCensus:TracePath"].ShouldBe("/tmp/trace.jsonl");
	}

	[Fact]
	public void ParseIsCaseInsensitiveOnTheSubcommand()
	{
		var result = CommandLineArgumentParser.Parse(["Census", "/tmp/trace.jsonl"]);

		result["AutoWrongCensus:Command"].ShouldBe("census");
	}

	[Fact]
	public void ParseReturnsEmptyForUnusableArguments()
	{
		CommandLineArgumentParser.Parse([]).ShouldBeEmpty();
		CommandLineArgumentParser.Parse(["bogus", "/tmp/trace.jsonl"]).ShouldBeEmpty();
		CommandLineArgumentParser.Parse(["census"]).ShouldBeEmpty();
		CommandLineArgumentParser.Parse(["pairs", "/tmp/census.tsv"]).ShouldBeEmpty();
	}
}
