{"content":"using LetUsCook.AutoWrongCensus.HostedServices;
using LetUsCook.AutoWrongCensus.Options;

using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

namespace LetUsCook.AutoWrongCensus;

/// <summary>
/// The console entry point, extracted from <c>Program.cs</c> so the tests can drive the exact host
/// graph the CLI runs (F-428 P12.13): same <see cref="AutoWrongCensusHostBuilderFactory"/>,
/// same hosted service, same exit code.
/// </summary>
public static class AutoWrongCensusCli
{
	/// <summary>Runs one census/pairs invocation and returns the process exit code.</summary>
	/// <param name="args">CLI arguments: <c>census &lt;trace.jsonl&gt;</c> or <c>pairs &lt;census.tsv&gt; &lt;trace.jsonl&gt;</c>.</param>
	/// <param name="output">TSV sink; defaults to <see cref="System.Console.Out"/>.</param>
	/// <param name="error">Summary/diagnostics sink; defaults to <see cref="System.Console.Error"/>.</param>
	/// <returns>0 on success; 1 on a missing file, a refused set, or unusable arguments.</returns>
	public static async Task<int> RunAsync(
		string[] args,
		System.IO.TextWriter? output = null,
		System.IO.TextWriter? error = null)
	{
		ArgumentNullException.ThrowIfNull(args);

		if (Array.Exists(args, a => a.Equals("--help", StringComparison.OrdinalIgnoreCase) || a.Equals("-h", StringComparison.OrdinalIgnoreCase)))
		{
			AutoWrongCensusUsage.Print();
			return 0;
		}

		var builder = AutoWrongCensusHostBuilderFactory.Create(args, output, error);
		var host = builder.Build();

		var hostedService = host.Services.GetRequiredService<AutoWrongCensusHostedService>();
		await host.RunAsync().ConfigureAwait(false);
		return hostedService.ExitCode;
	}
}
