using Shouldly;

using Xunit;

namespace LetUsCook.AutoWrongCensus.Tests.Options;

public sealed class CommandLineArgumentParserTests
{
	[Fact]
	public void ParseMapsCensusWithTracePath()
	{
		var result = CommandLineArgumentParser.Parse(["census", "/tmp/base-debug.jsonl"]);

		result["AutoWrongCensus:Command"].ShouldBe("census");
		result["AutoWrongCensus:TracePath"].ShouldBe("/tmp/base-debug.jsonl");
	}

	[Fact]
	public void ParseMapsPairsWithCensusTsvAndTracePath()
	{
		var result = CommandLineArgumentParser.Parse(["pairs", "/tmp/census-debug.tsv", "/tmp/base-debug.jsonl"]);

		result["AutoWrongCensus:Command"].ShouldBe("pairs");
		result["AutoWrongCensus:CensusTsvPath"].ShouldBe("/tmp/census-debug.tsv");
		result["AutoWrongCensus:TracePath"].ShouldBe("/tmp/base-debug.jsonl");
	}

	[Fact]
	public void ParseReturnsEmptyForUnknownCommand()
	{
		CommandLineArgumentParser.Parse(["bogus", "/tmp/x.jsonl"]).ShouldBeEmpty();
	}

	[Fact]
	public void ParseReturnsEmptyForCensusWithoutPath()
	{
		CommandLineArgumentParser.Parse(["census"]).ShouldBeEmpty();
	}

	[Fact]
	public void ParseReturnsEmptyForPairsWithOnePath()
	{
		CommandLineArgumentParser.Parse(["pairs", "/tmp/census.tsv"]).ShouldBeEmpty();
	}

	[Fact]
	public void ParseIsCaseInsensitiveOnTheSubcommand()
	{
		var result = CommandLineArgumentParser.Parse(["CENSUS", "/tmp/x.jsonl"]);

		result["AutoWrongCensus:Command"].ShouldBe("census");
	}
}
