namespace LetUsCook.AutoWrongCensus.Tests;

/// <summary>
/// Builds trace records shaped exactly like the HoldoutGate <c>--trace-file</c> JSONL:
/// camelCase fields, per-line atoms with path/reused/parsedName/linkedIngredientId/outcome.
/// </summary>
public static class TestTraces
{
	/// <summary>One trace line with a single atom; the shape every census input has.</summary>
	public static TraceLine Line(
		string holdoutId,
		int lineIndex,
		string rawText,
		string? expectedDesc,
		string? expectedType,
		string? actualDesc,
		string? actualType,
		string path,
		bool reused,
		string parsedName,
		string? linkedIngredientId = null,
		string set = "debug") => new()
		{
			RawText = rawText,
			HoldoutId = holdoutId,
			LineIndex = lineIndex,
			Set = set,
			Auto = true,
			Correct = false,
			ExpectedDescriptions = expectedDesc is null ? [] : [expectedDesc],
			ExpectedDataTypes = expectedType is null ? [] : [expectedType],
			ActualDescriptions = actualDesc is null ? [] : [actualDesc],
			ActualDataTypes = actualType is null ? [] : [actualType],
			Atoms = [Atom(path, reused, parsedName, linkedIngredientId)],
		};

	/// <summary>A correct (non-auto-wrong) line, for the runner's filtering.</summary>
	public static TraceLine CorrectLine(string holdoutId, int lineIndex, string rawText, string set = "debug") => new()
	{
		RawText = rawText,
		HoldoutId = holdoutId,
		LineIndex = lineIndex,
		Set = set,
		Auto = true,
		Correct = true,
		ExpectedDescriptions = ["Salt, table, iodized"],
		ExpectedDataTypes = ["Foundation"],
		ActualDescriptions = ["Salt, table, iodized"],
		ActualDataTypes = ["Foundation"],
		Atoms = [Atom("ranker", true, "salt", "salt")],
	};

	/// <summary>One accepted atom.</summary>
	public static TraceAtom Atom(string path, bool reused, string parsedName, string? linkedIngredientId = null) => new()
	{
		Path = path,
		Reused = reused,
		ParsedName = parsedName,
		LinkedIngredientId = linkedIngredientId,
		Outcome = "accepted",
	};
}
