using LetUsCook.AutoWrongCensus.Options;

using Shouldly;

using Xunit;

namespace LetUsCook.AutoWrongCensus.Tests.Services;

/// <summary>
/// The CLI contract through the real entry point (<see cref="AutoWrongCensusCli.RunAsync"/>, the same
/// host graph <c>Program.cs</c> runs): exit codes, refusals, the golden TSV, and the stderr summary.
/// </summary>
public sealed class AutoWrongCensusCliTests
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	[Fact]
	public async Task HelpReturnsZero()
	{
		(await AutoWrongCensusCli.RunAsync(["--help"], new StringWriter(), new StringWriter())).ShouldBe(0);
	}

	[Fact]
	public async Task CensusOnAMissingFileExitsOneAndRefusesOnStderr()
	{
		var error = new StringWriter();
		var exit = await AutoWrongCensusCli.RunAsync(["census", "/nonexistent/trace.jsonl"], new StringWriter(), error);

		exit.ShouldBe(1);
		error.ToString().ShouldContain("refused").ShouldContain("/nonexistent/trace.jsonl");
	}

	[Fact]
	public async Task CensusRefusesASealedTraceWithoutClassifying()
	{
		var path = WriteTraceFile([Record("debug:sealed-recipe", 0, "sealed")]);
		var output = new StringWriter();
		var error = new StringWriter();

		var exit = await AutoWrongCensusCli.RunAsync(["census", path], output, error);

		exit.ShouldBe(1);
		error.ToString().ShouldContain("sealed").ShouldContain("D-029");
		output.ToString().ShouldBe(string.Empty);
	}

	[Fact]
	public async Task CensusRefusesAnySetOtherThanDebugOrBatch()
	{
		var path = WriteTraceFile([Record("debug:holdout-recipe", 0, "holdout")]);
		var error = new StringWriter();

		var exit = await AutoWrongCensusCli.RunAsync(["census", path], new StringWriter(), error);

		exit.ShouldBe(1);
		error.ToString().ShouldContain("D-029");
	}

	[Fact]
	public async Task CensusRefusesAnUnknownAtomPath()
	{
		var line = Record("debug:fixture", 0, "debug");
		line.Atoms = [new TraceAtom { Path = "hand-fed", ParsedName = "mystery", Outcome = "accepted" }];
		var path = WriteTraceFile([line]);
		var error = new StringWriter();

		var exit = await AutoWrongCensusCli.RunAsync(["census", path], new StringWriter(), error);

		exit.ShouldBe(1);
		error.ToString().ShouldContain("hand-fed");
	}

	[Fact]
	public async Task UnusableArgumentsExitOneWithUsageOnStderr()
	{
		var error = new StringWriter();
		(await AutoWrongCensusCli.RunAsync([], new StringWriter(), error)).ShouldBe(1);
		error.ToString().ShouldContain("usage");

		error.GetStringBuilder().Clear();
		(await AutoWrongCensusCli.RunAsync(["census"], new StringWriter(), error)).ShouldBe(1);
		error.ToString().ShouldContain("usage");
	}

	[Fact]
	public async Task CensusWritesTheGoldenTsvAndAMatchingSummary()
	{
		var path = WriteTraceFile(GoldenRecords());
		var output = new StringWriter();
		var error = new StringWriter();

		var exit = await AutoWrongCensusCli.RunAsync(["census", path], output, error);

		exit.ShouldBe(0);
		output.ToString().ShouldBe(GoldenTsv);
		error.ToString().ShouldContain("autoWrongCensus traced=10 autoWrong=10");
		error.ToString().ShouldNotContain("Hosting environment");

		// The stderr matrix must agree with the TSV row-for-row.
		var matrix = error.ToString().Split('\n').Where(l => l.Contains('\t')).Skip(1).ToList();
		matrix.Count.ShouldBe(8); // the eight relation × site cells of the golden set
		foreach (var row in output.ToString().Split('\n').Skip(1))
		{
			var cells = row.Split('\t');
			matrix.ShouldContain($"{cells[3]}\t{cells[4]}\t1");
		}
	}

	[Fact]
	public async Task PairsEmitsOnlyWindowRowsWithCompoundOrOtherRoute()
	{
		var tracePath = WriteTraceFile([
			Record("debug:a", 1, "debug"),
			Record("debug:b", 2, "debug"),
			Record("debug:c", 3, "debug"),
			Record("debug:d", 4, "debug"),
		]);
		var censusPath = Path.Combine(Path.GetTempPath(), $"pw1213-census-{Guid.NewGuid():N}.tsv");
		await File.WriteAllTextAsync(censusPath,
			"holdoutId\tlineIndex\tblocker\troute\n" +
			"debug:a\t1\twindow\tcompound\n" +
			"debug:b\t2\twindow\tother\n" +
			"debug:c\t3\tmapping-reuse\tcompound\n" +
			"debug:d\t4\twindow\tparser-word-lost\n");

		var output = new StringWriter();
		var error = new StringWriter();
		var exit = await AutoWrongCensusCli.RunAsync(["pairs", censusPath, tracePath], output, error);

		exit.ShouldBe(0);
		output.ToString().ShouldBe(
			"holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText\n" +
			"debug:a\t1\t\t\t\n" +
			"debug:b\t2\t\t\t\n");
		error.ToString().ShouldContain("pairs emitted=2 unmatchedCensusRows=0");
	}

	[Fact]
	public async Task PairsOnAMissingCensusTsvExitsOne()
	{
		var tracePath = WriteTraceFile([Record("debug:a", 1, "debug")]);
		var error = new StringWriter();

		var exit = await AutoWrongCensusCli.RunAsync(["pairs", "/nonexistent/census.tsv", tracePath], new StringWriter(), error);

		exit.ShouldBe(1);
		error.ToString().ShouldContain("refused");
	}

	/// <summary>The ten golden lines: every relation class and every site, including the brief §2 lines.</summary>
	private static List<TraceLine> GoldenRecords() =>
	[
			Record("debug:golden", 0, "debug") with
			{
				RawText = "2 tsp good olive oil",
				ExpectedDescriptions = [],
				ExpectedDataTypes = [],
				ActualDescriptions = ["Oil, olive, salad or cooking"],
				ActualDataTypes = ["SrLegacy"],
				Atoms = [new TraceAtom { Path = "curated", ParsedName = "olive oil", Outcome = "accepted" }],
			},
			Record("debug:golden", 1, "debug") with
			{
				RawText = "1 (28 ounce) can crushed tomatoes",
				ExpectedDescriptions = ["Tomatoes, crushed, canned"],
				ExpectedDataTypes = ["Foundation"],
				ActualDescriptions = ["Tomato, roma"],
				ActualDataTypes = ["Foundation"],
				Atoms = [new TraceAtom { Path = "ranker", Reused = true, ParsedName = "tomatoes", LinkedIngredientId = "tomato", Outcome = "accepted" }],
			},
			Record("debug:golden", 2, "debug") with
			{
				RawText = "3 cups bread crumbs, or as needed",
				ExpectedDescriptions = ["Bread, crumbs, dry, grated, plain"],
				ExpectedDataTypes = ["SrLegacy"],
				ActualDescriptions = ["Bread, white, commercially prepared (includes soft bread crumbs)"],
				ActualDataTypes = ["SrLegacy"],
				Atoms = [new TraceAtom { Path = "override", Reused = true, ParsedName = "bread", LinkedIngredientId = "bread", Outcome = "accepted" }],
			},
			Record("debug:golden", 3, "debug") with
			{
				RawText = "1/2 cup finely chopped blanched almonds",
				ExpectedDescriptions = ["Nuts, almonds, blanched"],
				ExpectedDataTypes = ["SrLegacy"],
				ActualDescriptions = ["Nuts, almonds, whole, raw"],
				ActualDataTypes = ["Foundation"],
				Atoms = [new TraceAtom { Path = "ranker", Reused = true, ParsedName = "almonds", LinkedIngredientId = "almond", Outcome = "accepted" }],
			},
			Record("debug:golden", 4, "debug") with
			{
				RawText = "2 carrots, chopped",
				ExpectedDescriptions = ["Carrots, raw"],
				ExpectedDataTypes = ["SrLegacy"],
				ActualDescriptions = ["Carrots, raw"],
				ActualDataTypes = ["Foundation"],
				Atoms = [new TraceAtom { Path = "ranker", Reused = true, ParsedName = "carrots", LinkedIngredientId = "carrot", Outcome = "accepted" }],
