		"debug:golden\t1\tdebug\tpack-unit-state\treuse\t\tFoundation\tFoundation\tNone\tCanned\ttomatoes\ttomato crushed\tTomato, roma\tTomatoes, crushed, canned\t1 (28 ounce) can crushed tomatoes\n" +
		"debug:golden\t2\tdebug\tcompound-head-lost\toverride\tno\tSrLegacy\tSrLegacy\tNone\tDried\tbread\tbread crumb\tBread, white, commercially prepared (includes soft bread crumbs)\tBread, crumbs, dry, grated, plain\t3 cups bread crumbs, or as needed\n" +
		"debug:golden\t3\tdebug\tstate-mismatch\treuse\t\tFoundation\tSrLegacy\tRaw\tNone\talmonds\tnut almond blanched\tNuts, almonds, whole, raw\tNuts, almonds, blanched\t1/2 cup finely chopped blanched almonds\n" +
		"debug:golden\t4\tdebug\trow-choice-tier\treuse\t\tFoundation\tSrLegacy\tRaw\tRaw\tcarrots\tcarrot\tCarrots, raw\tCarrots, raw\t2 carrots, chopped\n" +
		"debug:golden\t5\tdebug\tsame-head-other-qualifier\tranker\t\tSrLegacy\tSrLegacy\tNone\tNone\tlow fat milk\tmilk low fat with calcium added\tMilk, low fat\tMilk, low fat, with calcium added\t1 cup 2% milk\n" +
