		"debug:golden\t7\tdebug\tother\treuse\t\t\tSrLegacy\tNone\tNone\tcelery leaves\tcelery leaf\tCelery\tCelery, leaves\t2 stalks celery\n" +
		"debug:golden\t8\tdebug\tpack-unit-state\treuse\t\tSrLegacy\tBranded\tRaw\tCanned\tapricots\tapricot\tApricots, raw\tApricots, canned, drained, packed in heavy syrup, sweetened\t1 (4 ounce) jar apricot baby food\n" +
		"debug:golden\t9\tdebug\tsame-head-other-qualifier\toverride\tyes\tSrLegacy\tSrLegacy\tNone\tNone\tamaretto\tcherry sour red\tCherries, sour, maraschino, glazed\tCherries, sour, red\tamaretto\n";

	private static TraceLine Record(string holdoutId, int lineIndex, string set) =>
		new()
		{
			RawText = "fixture line",
			HoldoutId = holdoutId,
			LineIndex = lineIndex,
			Set = set,
			Auto = true,
			Correct = false,
			ExpectedDescriptions = ["Onions, raw"],
			ExpectedDataTypes = ["SrLegacy"],
			ActualDescriptions = ["Garlic, raw"],
			ActualDataTypes = ["Foundation"],
			Atoms = [new TraceAtom { Path = "ranker", ParsedName = "onion", Outcome = "accepted" }],
		};

	private static string WriteTraceFile(IEnumerable<TraceLine> records)
	{
		var path = Path.Combine(Path.GetTempPath(), $"pw1213-trace-{Guid.NewGuid():N}.jsonl");
		var builder = new StringBuilder();
		foreach (var record in records)
		{
			builder.AppendLine(JsonSerializer.Serialize(record, JsonOptions));
		}

		File.WriteAllText(path, builder.ToString());
		return path;
	}
}
