{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;

using Shouldly;

using Xunit;

namespace LetUsCook.AutoWrongCensus.Tests;

/// <summary>
/// The CLI contract through the real entry point (<see cref="AutoWrongCensusCli.RunAsync"/> → the same
/// host graph <c>Program.cs</c> builds): golden TSV, relation × site summary consistency, set refusal
/// (D-029), missing-input and unknown-path exits.
/// </summary>
public sealed class AutoWrongCensusCliTests
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	/// <summary>Full TSV written by the census for the fixture below; columns per brief §4 (with header).</summary>
	private const string GoldenTsv =
		"holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText\n" +
		"debug:nolabel\t0\tdebug\tno-label\tcurated\t\tSrLegacy\t\tNone\t\tolive oil\t\tOil, olive, salad or cooking\t\t2 tsp good olive oil\n" +
		"debug:canned\t0\tdebug\tpack-unit-state\treuse\t\tFoundation\tFoundation\tNone\tCanned\ttomatoes\ttomato crushed\tTomato, roma\tTomatoes, crushed, canned\t1 (28 ounce) can crushed tomatoes\n" +
		"debug:breadcrumbs\t0\tdebug\tcompound-head-lost\toverride\tno\tSrLegacy\tSrLegacy\tNone\tDried\tbread\tbread crumb\tBread, white, commercially prepared (includes soft bread crumbs)\tBread, crumbs, dry, grated, plain\t3 cups bread crumbs, or as needed\n" +
		"debug:almonds\t0\tdebug\tstate-mismatch\treuse\t\tFoundation\tSrLegacy\tRaw\tNone\talmonds\tnut almond blanched\tNuts, almonds, whole, raw\tNuts, almonds, blanched\t1/2 cup finely chopped blanched almonds\n" +
		"debug:tier\t0\tdebug\trow-choice-tier\treuse\t\tFoundation\tSrLegacy\tRaw\tRaw\tcarrots\tcarrot\tCarrots, raw\tCarrots, raw\t2 carrots, chopped\n" +
		"debug:qualifier\t0\tdebug\tsame-head-other-qualifier\tranker\t\tSrLegacy\tSrLegacy\tNone\tNone\tlow fat milk\tmilk\tMilk, low fat\tMilk, low fat, with calcium added\t1 cup 2% milk\n" +
		"debug:sibling\t0\tdebug\tsibling-food\toverride\tno\tFoundation\tSrLegacy\tRaw\tRaw\tonion\tonion\tGarlic, raw\tOnions, raw\t1 onion, diced\n" +
		"debug:missingtier\t0\tdebug\tother\treuse\t\t\tSrLegacy\t\t\tcelery leaves\tcelery leaf\tCelery\tCelery, leaves\t2 stalks celery\n" +
		"debug:jar\t0\tdebug\tpack-unit-state\treuse\t\tSrLegacy\tBranded\tNone\tCanned\tapricots\tapricot\tApricots, raw\tApricots, canned, drained, packed in heavy syrup, sweetened\t1 (4 ounce) jar apricot baby food\n" +
		"debug:amaretto\t0\tdebug\tsame-head-other-qualifier\toverride\tyes\tSrLegacy\tSrLegacy\tNone\tNone\tamaretto\tcherry\tCherries, sour, maraschino, glazed\tCherries, sour, red\tamaretto\n";

	[Fact]
	public async Task CensusWritesTheGoldenTsvThroughTheConsoleEntryPointAsync()
	{
		var tracePath = WriteTrace(BuildCensusFixture());

		using var output = new StringWriter();
		using var error = new StringWriter();
		var exit = await AutoWrongCensusCli.RunAsync(["census", tracePath], output, error);

		exit.ShouldBe(0);
		output.ToString().ReplaceLineEndings("\n").ShouldBe(GoldenTsv);
	}

	[Fact]
	public async Task CensusSummaryMatrixEqualsTheWrittenTsvCellsAsync()
	{
		var tracePath = WriteTrace(BuildCensusFixture());

		using var output = new StringWriter();
		using var error = new StringWriter();
		await AutoWrongCensusCli.RunAsync(["census", tracePath], output, error);

		var tsvLines = output.ToString().ReplaceLineEndings("\n").TrimEnd('\n').Split('\n').Skip(1).ToArray();
		var expectedCounts = tsvLines
			.Select(l => l.Split('\t'))
			.GroupBy(cells => (cells[3], cells[4]))
			.ToDictionary(g => g.Key, g => g.Count());

		var matrix = error.ToString().ReplaceLineEndings("\n").TrimEnd('\n').Split('\n')
			.SkipWhile(l => l != "relation\tsite\tcount")
