	public void AMapExpandedRawPhraseStillSatisfiesTheAnyTailTokenEvidence()
	{
		// NO-GO-2 finding 1: the evidence quantifier is "at least one tail token" — the key's head
		// phrase is `chicken breast boneless skinless` (four tokens) and rawText names only `breast`
		// (the normalizer's phrase map expands "chicken fillet" to "chicken breast"); a mutation
		// requiring ALL tail tokens must fail this line.
		var line = Line(
			rawText: "2 piece Chicken fillet",
			keyDescriptions: ["Chicken, breast, boneless, skinless, raw"],
			keyTypes: ["SrLegacy"],
			acceptedDescriptions: ["Chicken, broilers or fryers, meat and skin, raw"],
			acceptedTypes: ["Foundation"],
			path: "ranker",
			reused: true,
			parsedName: "Chicken");

		var result = Classifier.Classify(line);

		result.Relation.ShouldBe(AutoWrongClassifier.RelationCompoundHeadLost);
	}

	[Fact]
	public void MapValuesAreSingularisedBeforeTheEvidenceCheck()
	{
		// NO-GO-2 finding 2: the normalizer's phrase map can hand back plural values
		// ("habalapethi" -> "rice flakes") that the -s rule never touches; the outer
		// SingularTokens fold is what makes `flake` match the key's head.
		var line = Line(
			rawText: "200 g habalapethi",
			keyDescriptions: ["Rice, flakes, raw"],
			keyTypes: ["Foundation"],
			acceptedDescriptions: ["Rice, white, long grain, parboiled, cooked"],
			acceptedTypes: ["Survey"],
			path: "ranker",
			reused: true,
			parsedName: "rice");

		var result = Classifier.Classify(line);

		result.Relation.ShouldBe(AutoWrongClassifier.RelationCompoundHeadLost);
	}

